mSTABBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "mSTABBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jYS",
                name = "mSTAB",
                version = c(1,0,0),
                options = options,
                results = mSTABResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Stability Analysis (ICH Q1E)
#'
#' Evaluation of stability data and shelf life estimation according to the ICH 
#' Q1E guideline using ANCOVA poolability testing and specification-directed 
#' confidence bounds.
#' @param data .
#' @param dep .
#' @param time .
#' @param batch .
#' @param specType .
#' @param lsl .
#' @param usl .
#' @param alphaPool .
#' @param confLevel .
#' @param modelChoice .
#' @param trans .
#' @param dep2 .
#' @param specType2 .
#' @param lsl2 .
#' @param usl2 .
#' @param trans2 .
#' @param dep3 .
#' @param specType3 .
#' @param lsl3 .
#' @param usl3 .
#' @param trans3 .
#' @param dep4 .
#' @param specType4 .
#' @param lsl4 .
#' @param usl4 .
#' @param trans4 .
#' @param dep5 .
#' @param specType5 .
#' @param lsl5 .
#' @param usl5 .
#' @param trans5 .
#' @param showMultiShelfTable .
#' @param showMultiBatchTable .
#' @param showMultiShelfPlot .
#' @param detailAttr .
#' @param showArrh .
#' @param tempVar .
#' @param arrhEa .
#' @param arrhTempAcc .
#' @param arrhRhAcc .
#' @param arrhTempLong .
#' @param arrhRhLong .
#' @param arrhB .
#' @param showArrhSens .
#' @param showArrhPlot .
#' @param showArrhTrajPlot .
#' @param accelCondition .
#' @param studyDuration .
#' @param showPoolTable .
#' @param showShelfTable .
#' @param showCoefTable .
#' @param showDiagTable .
#' @param showStabPlot .
#' @param showDiagPlot .
#' @param showShelfPlot .
#' @param showFacetPlot .
#' @param showRatePlot .
#' @param showPredPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$poolTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$shelfTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coefTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$diagTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$stabPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$shelfPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$facetPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$ratePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$predPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$diagPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$multiShelfTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$multiBatchTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$multiShelfPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$arrhTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$arrhSensTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$arrhRegTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$arrhPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$arrhTrajPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$poolTable$asDF}
#'
#' \code{as.data.frame(results$poolTable)}
#'
#' @export
mSTAB <- function(
    data,
    dep,
    time,
    batch,
    specType = "lower",
    lsl = 90,
    usl = 105,
    alphaPool = 0.25,
    confLevel = 0.95,
    modelChoice = "auto",
    trans = "none",
    dep2,
    specType2 = "upper",
    lsl2 = 0,
    usl2 = 1,
    trans2 = "none",
    dep3,
    specType3 = "lower",
    lsl3 = 80,
    usl3 = 100,
    trans3 = "none",
    dep4,
    specType4 = "lower",
    lsl4 = 90,
    usl4 = 110,
    trans4 = "none",
    dep5,
    specType5 = "upper",
    lsl5 = 0,
    usl5 = 5,
    trans5 = "none",
    showMultiShelfTable = TRUE,
    showMultiBatchTable = TRUE,
    showMultiShelfPlot = TRUE,
    detailAttr = "worst",
    showArrh = FALSE,
    tempVar,
    arrhEa = 83.14,
    arrhTempAcc = 40,
    arrhRhAcc = 75,
    arrhTempLong = 25,
    arrhRhLong = 60,
    arrhB = 0,
    showArrhSens = TRUE,
    showArrhPlot = TRUE,
    showArrhTrajPlot = TRUE,
    accelCondition = "none",
    studyDuration = 0,
    showPoolTable = TRUE,
    showShelfTable = TRUE,
    showCoefTable = TRUE,
    showDiagTable = TRUE,
    showStabPlot = TRUE,
    showDiagPlot = FALSE,
    showShelfPlot = FALSE,
    showFacetPlot = FALSE,
    showRatePlot = FALSE,
    showPredPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("mSTAB requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(batch)) batch <- jmvcore::resolveQuo(jmvcore::enquo(batch))
    if ( ! missing(dep2)) dep2 <- jmvcore::resolveQuo(jmvcore::enquo(dep2))
    if ( ! missing(dep3)) dep3 <- jmvcore::resolveQuo(jmvcore::enquo(dep3))
    if ( ! missing(dep4)) dep4 <- jmvcore::resolveQuo(jmvcore::enquo(dep4))
    if ( ! missing(dep5)) dep5 <- jmvcore::resolveQuo(jmvcore::enquo(dep5))
    if ( ! missing(tempVar)) tempVar <- jmvcore::resolveQuo(jmvcore::enquo(tempVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(batch), batch, NULL),
            `if`( ! missing(dep2), dep2, NULL),
            `if`( ! missing(dep3), dep3, NULL),
            `if`( ! missing(dep4), dep4, NULL),
            `if`( ! missing(dep5), dep5, NULL),
            `if`( ! missing(tempVar), tempVar, NULL))

    for (v in batch) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- mSTABOptions$new(
        dep = dep,
        time = time,
        batch = batch,
        specType = specType,
        lsl = lsl,
        usl = usl,
        alphaPool = alphaPool,
        confLevel = confLevel,
        modelChoice = modelChoice,
        trans = trans,
        dep2 = dep2,
        specType2 = specType2,
        lsl2 = lsl2,
        usl2 = usl2,
        trans2 = trans2,
        dep3 = dep3,
        specType3 = specType3,
        lsl3 = lsl3,
        usl3 = usl3,
        trans3 = trans3,
        dep4 = dep4,
        specType4 = specType4,
        lsl4 = lsl4,
        usl4 = usl4,
        trans4 = trans4,
        dep5 = dep5,
        specType5 = specType5,
        lsl5 = lsl5,
        usl5 = usl5,
        trans5 = trans5,
        showMultiShelfTable = showMultiShelfTable,
        showMultiBatchTable = showMultiBatchTable,
        showMultiShelfPlot = showMultiShelfPlot,
        detailAttr = detailAttr,
        showArrh = showArrh,
        tempVar = tempVar,
        arrhEa = arrhEa,
        arrhTempAcc = arrhTempAcc,
        arrhRhAcc = arrhRhAcc,
        arrhTempLong = arrhTempLong,
        arrhRhLong = arrhRhLong,
        arrhB = arrhB,
        showArrhSens = showArrhSens,
        showArrhPlot = showArrhPlot,
        showArrhTrajPlot = showArrhTrajPlot,
        accelCondition = accelCondition,
        studyDuration = studyDuration,
        showPoolTable = showPoolTable,
        showShelfTable = showShelfTable,
        showCoefTable = showCoefTable,
        showDiagTable = showDiagTable,
        showStabPlot = showStabPlot,
        showDiagPlot = showDiagPlot,
        showShelfPlot = showShelfPlot,
        showFacetPlot = showFacetPlot,
        showRatePlot = showRatePlot,
        showPredPlot = showPredPlot)

    analysis <- mSTABClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

